use crate::api::client::ApiClient;
use crate::constants;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;

const ROUNDING_SECONDS: i64 = 15 * 60;
const MINIMUM_SECONDS: i64 = 30 * 60;

pub struct InvoiceCommand;

fn billed_seconds(duration: i64) -> i64 {
    let rounded = ((duration + ROUNDING_SECONDS - 1) / ROUNDING_SECONDS) * ROUNDING_SECONDS;
    rounded.max(MINIMUM_SECONDS)
}

fn invoice_totals(entries: impl IntoIterator<Item = TimeEntry>) -> Vec<(String, i64)> {
    let mut totals = HashMap::<String, i64>::new();

    for entry in entries {
        if !entry.billable || entry.is_running() || entry.stop.is_none() {
            continue;
        }

        let project = entry
            .project
            .map(|project| project.name)
            .unwrap_or_else(|| constants::NO_PROJECT.to_string());
        *totals.entry(project).or_default() += billed_seconds(entry.duration);
    }

    let mut totals: Vec<_> = totals.into_iter().collect();
    totals.sort_by(|(left_name, left_seconds), (right_name, right_seconds)| {
        right_seconds
            .cmp(left_seconds)
            .then_with(|| left_name.cmp(right_name))
    });
    totals
}

impl InvoiceCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = if since.is_some() || until.is_some() {
            utilities::normalize_time_entry_list_filters(since, until)?
        } else {
            (None, None)
        };
        let totals = invoice_totals(api_client.get_time_entries_filtered(since, until).await?);

        if totals.is_empty() {
            println!("(no data)");
        } else {
            let total = invoice_totals_from_output(&totals);
            for (project, seconds) in &totals {
                println!("{seconds}s  {project}");
            }
            println!("{total}s  Total");
        }

        Ok(())
    }
}

fn invoice_totals_from_output(totals: &[(String, i64)]) -> i64 {
    totals.iter().map(|(_, seconds)| seconds).sum()
}

